        json{{"skills", skill}},
        json{{"skills", json::array({skill})}, {"index", true}},
        json{{"skills", json::array({missing_trigger})}},
        json{{"skills", json::array({described})}},  // a key the protocol does not have
        with("name", "Model_Opened"),
