                                     {"sessionId", std::to_string(snapshot.session.value())},
                                     {"revision", snapshot.revision}}
                                    .dump();
        activity->state = ToolState::Succeeded;
        wait = m_slice_waits.erase(wait);
        notify(*activity);
    }
}

